BEGIN TRANSACTION;
CREATE TABLE "system_sessions" (session_id VARCHAR NOT NULL, session_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, user_id VARCHAR, session_data JSON, metadata JSON, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (session_id));
INSERT INTO "system_sessions" VALUES('thread_summary','agent','system:internal',NULL,NULL,'{"session_state": {}}','null',1750000010,1750000010);
INSERT INTO "system_sessions" VALUES('routing','agent','system:internal',NULL,NULL,'{"session_state": {}}','null',1750000020,1750000020);
CREATE TABLE "system_sessions_log_messages" (run_id TEXT NOT NULL REFERENCES "system_sessions_log_runs"(run_id) ON DELETE CASCADE, message_id TEXT NOT NULL, ord INTEGER NOT NULL, folded_by INTEGER, data TEXT NOT NULL, PRIMARY KEY (run_id, message_id));
CREATE TABLE "system_sessions_log_meta" (id INTEGER PRIMARY KEY CHECK (id = 1), version INTEGER NOT NULL, next_seq INTEGER NOT NULL);
INSERT INTO "system_sessions_log_meta" VALUES(1,3,1);
CREATE TABLE "system_sessions_log_removed" (run_id TEXT NOT NULL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "system_sessions"(session_id) ON DELETE CASCADE);
CREATE TABLE "system_sessions_log_runs" (run_id TEXT NOT NULL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "system_sessions"(session_id) ON DELETE CASCADE, parent_run_id TEXT, kind TEXT NOT NULL, scope_key TEXT NOT NULL, status TEXT NOT NULL, seq INTEGER NOT NULL, folded_by INTEGER, has_tools INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, metadata TEXT, record TEXT NOT NULL, requirements TEXT);
CREATE TABLE "system_sessions_log_summaries" (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL REFERENCES "system_sessions"(session_id) ON DELETE CASCADE, scope_key TEXT NOT NULL, through INTEGER NOT NULL, legacy INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, fold_run_id TEXT, summary TEXT, event_ids TEXT NOT NULL DEFAULT '[]', seen_event_ids TEXT NOT NULL DEFAULT '[]', fold_event_ids TEXT, fold_seen_event_ids TEXT);
CREATE TABLE "system_sessions_log_tools" (run_id TEXT NOT NULL REFERENCES "system_sessions_log_runs"(run_id) ON DELETE CASCADE, ord INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (run_id, ord));
CREATE TABLE "system_sessions_usage" (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "system_sessions"(session_id) ON DELETE CASCADE, run_id TEXT, usage_data TEXT, UNIQUE(session_id, run_id));
INSERT INTO "system_sessions_usage" VALUES(1,'thread_summary','thread_summary:s1','{"run_id": "thread_summary:s1", "parent_run_id": null, "team_id": null, "user_id": null, "model_provider": "Synthetic", "model": "synthetic-model", "created_at": 1750000010.0, "metrics": {"input_tokens": 30, "output_tokens": 3, "total_tokens": 33}, "requests": [{"created_at": 1750000010.0, "metrics": {"input_tokens": 30, "output_tokens": 3, "total_tokens": 33}, "model": "synthetic-model", "model_provider": "Synthetic"}], "kind": "thread_summary"}');
INSERT INTO "system_sessions_usage" VALUES(2,'routing','routing:s2','{"run_id": "routing:s2", "parent_run_id": null, "team_id": null, "user_id": null, "model_provider": "Synthetic", "model": "synthetic-model", "created_at": 1750000020.0, "metrics": {"input_tokens": 30, "output_tokens": 3, "total_tokens": 33}, "requests": [{"created_at": 1750000020.0, "metrics": {"input_tokens": 30, "output_tokens": 3, "total_tokens": 33}, "model": "synthetic-model", "model_provider": "Synthetic"}], "kind": "routing"}');
CREATE INDEX "idx_system_sessions_session_type" ON "system_sessions" (session_type);
CREATE INDEX "idx_system_sessions_log_runs_session_id_seq" ON "system_sessions_log_runs" (session_id, seq);
CREATE INDEX "idx_system_sessions_log_runs_parent_run_id" ON "system_sessions_log_runs" (parent_run_id);
CREATE INDEX "idx_system_sessions_log_messages_run_id_ord" ON "system_sessions_log_messages" (run_id, ord);
CREATE INDEX "idx_system_sessions_log_summaries_session_id_scope_key_id" ON "system_sessions_log_summaries" (session_id, scope_key, id);
DELETE FROM "sqlite_sequence";
COMMIT;
